22	/**
23	 * H2（MODE=MySQL）事务边界测试：验证同一行的真实更新会取得行级排他锁，
24	 * 第二个事务的同行更新必须阻塞至第一个事务提交或回滚。这是审核与禁飞区变更
25	 * 串行化、保证一致状态读取的数据库基础，不使用 mock 代替。
26	 */
27	@SpringBootTest
28	@DisplayName("H2 行级排他锁事务互斥")
29	class H2LockProbeTest {
30	
31	    @Autowired
32	    private DataSource dataSource;
33	    @Autowired
34	    private JdbcTemplate jdbc;
35	
36	    @Test
37	    @DisplayName("未提交的同行更新阻塞其他事务，提交后放行")
38	    void sameRowUpdateIsExclusiveUntilCommit() throws Exception {
39	        jdbc.update("UPDATE coord_lock SET touched = 0 WHERE id = 1");
40	        ExecutorService pool = Executors.newFixedThreadPool(2);
41	        CountDownLatch holderUpdated = new CountDownLatch(1);
42	        Connection holder = dataSource.getConnection();
43	        Connection waiter = dataSource.getConnection();
44	        try {
45	            holder.setAutoCommit(false);
46	            waiter.setAutoCommit(false);
47	
48	            Future<?> holdFuture = pool.submit(() -> {
49	                try (PreparedStatement ps = holder.prepareStatement(
50	                        "UPDATE coord_lock SET touched = touched + 1 WHERE id = 1")) {
51	                    ps.executeUpdate();
52	                } catch (Exception e) {
53	                    throw new RuntimeException(e);
54	                }
55	                holderUpdated.countDown();
56	                try {
57	                    Thread.sleep(1500);
58	                    holder.commit();
59	                } catch (InterruptedException e) {
60	                    Thread.currentThread().interrupt();
61	                } catch (Exception e) {
62	                    throw new RuntimeException(e);
63	                }
64	                return null;
65	            });
66	            assertTrue(holderUpdated.await(5, TimeUnit.SECONDS));
67	
68	            Future<Integer> waitFuture = pool.submit(() -> {
69	                try (PreparedStatement ps = waiter.prepareStatement(
70	                        "UPDATE coord_lock SET touched = touched + 1 WHERE id = 1")) {
71	                    return ps.executeUpdate();
72	                } catch (Exception e) {
73	                    throw new RuntimeException(e);
74	                }
75	            });
76	            // 持锁事务未提交时，等待方在 500ms 内拿不到锁
77	            boolean blocked = true;
78	            try {
79	                waitFuture.get(500, TimeUnit.MILLISECONDS);
80	                blocked = false;
81	            } catch (java.util.concurrent.TimeoutException expected) {
82	                // 预期：被行锁阻塞
83	            }
84	            assertTrue(blocked, "同行更新必须被未提交事务的行级排他锁阻塞");
85	
86	            holdFuture.get(10, TimeUnit.SECONDS);
87	            waitFuture.get(10, TimeUnit.SECONDS);
88	            waiter.commit();
89	
90	            // 两次更新均已提交：touched 增加 2
91	            Long touched = jdbc.queryForObject(
92	                    "SELECT touched FROM coord_lock WHERE id = 1", Long.class);
93	            assertEquals(2L, touched);
94	        } finally {
95	            holder.close();
96	            waiter.close();
97	            pool.shutdownNow();
98	        }
99	    }
100	
101	    @Test
102	    @DisplayName("持锁事务回滚后等待方立即获得锁，回滚更新不残留")
103	    void rollbackReleasesLock() throws Exception {
104	        jdbc.update("UPDATE coord_lock SET touched = 0 WHERE id = 1");
105	        ExecutorService pool = Executors.newFixedThreadPool(2);
106	        CountDownLatch holderUpdated = new CountDownLatch(1);
107	        Connection holder = dataSource.getConnection();
108	        Connection waiter = dataSource.getConnection();
109	        try {
110	            holder.setAutoCommit(false);
111	            waiter.setAutoCommit(false);
112	
113	            Future<?> holdFuture = pool.submit(() -> {
114	                try (PreparedStatement ps = holder.prepareStatement(
115	                        "UPDATE coord_lock SET touched = touched + 100 WHERE id = 1")) {
116	                    ps.executeUpdate();
117	                } catch (Exception e) {
118	                    throw new RuntimeException(e);
119	                }
120	                holderUpdated.countDown();
121	                try {
122	                    Thread.sleep(800);
123	                    holder.rollback();
124	                } catch (InterruptedException e) {
125	                    Thread.currentThread().interrupt();
126	                } catch (Exception e) {
127	                    throw new RuntimeException(e);
128	                }
129	                return null;
130	            });
131	            assertTrue(holderUpdated.await(5, TimeUnit.SECONDS));
132	
133	            Future<Integer> waitFuture = pool.submit(() -> {
134	                try (PreparedStatement ps = waiter.prepareStatement(
135	                        "UPDATE coord_lock SET touched = touched + 1 WHERE id = 1")) {
136	                    return ps.executeUpdate();
137	                } catch (Exception e) {
138	                    throw new RuntimeException(e);
139	                }
140	            });
141	            holdFuture.get(10, TimeUnit.SECONDS);
142	            waitFuture.get(10, TimeUnit.SECONDS);
143	            waiter.commit();
144	
145	            // 回滚方的 +100 不生效，等待方的 +1 生效
146	            Long touched = jdbc.queryForObject(
147	                    "SELECT touched FROM coord_lock WHERE id = 1", Long.class);
148	            assertFalse(touched >= 100, "回滚事务的更新不得残留");
149	            assertEquals(1L, touched);
150	        } finally {
151	            holder.close();
152	            waiter.close();
153	            pool.shutdownNow();
154	        }
