            throw new ApiException(HttpStatus.BAD_REQUEST, "INVALID_BAND_ID",
                    "高度带标识不能为空且不超过 64 字符");
        }
        if (!seenIds.add(dto.bandId())) {
            throw new ApiException(HttpStatus.BAD_REQUEST, "DUPLICATE_BAND_ID",
